if($page==='products'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$cats=$pdo->query('SELECT * FROM categories WHERE active=1 ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.english_name')->fetchAll();header_html('Products');?><h1>Products</h1><div class="card"><h2><?=$edit?'Edit':'Add'?> Product</h2><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Category</label><select name="category_id"><option value="0">No category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??0)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></p><p><label>English name (search)</label><input name="english_name" value="<?=e($edit['english_name']??'')?>" required></p><p><label>Tamil name (print)</label><input lang="ta" name="tamil_name" value="<?=e($edit['tamil_name']??'')?>" required></p><p><label>Unit</label><input name="unit" value="<?=e($edit['unit']??'Nos')?>" required></p><p><label>Default rate</label><input type="number" step="0.01" min="0" name="default_rate" value="<?=e($edit['default_rate']??'0')?>"></p><p><label><input style="width:auto" type="checkbox" name="active" <?=!$edit||$edit['active']?'checked':''?>> Active</label><br><button>Save Product</button></p></form></div><div class="card"><table><tr><th>English search name</th><th>Tamil print name</th><th>Category</th><th>Unit</th><th>Rate</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['english_name'])?></td><td lang="ta"><?=e($r['tamil_name'])?></td><td><?=e($r['category'])?></td><td><?=e($r['unit'])?></td><td><?=money($r['default_rate'])?></td><td><a href="?page=products&edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='customers'){$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$rows=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();header_html('Customers');?><h1>Customers & Balances</h1><div class="grid"><div class="card"><h2><?=$edit?'Edit':'Add'?> Customer</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_customer"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><p><label>Name</label><input name="name" value="<?=e($edit['name']??'')?>" required></p><p><label>WhatsApp Number</label><input name="mobile" inputmode="tel" placeholder="9677811194" value="<?=e($edit['mobile']??'')?>"><small class="muted">Enter a 10-digit Indian number. +91 is added automatically.</small></p><p><label>Address</label><textarea name="address"><?=e($edit['address']??'')?></textarea></p><p><label>Opening balance</label><input type="number" step="0.01" name="opening_balance" value="<?=e($edit['opening_balance']??'0')?>"></p><button>Save Customer</button></form></div><div class="card"><h2>Record Payment</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_payment"><p><label>Customer</label><select name="customer_id" required><option value="">Select</option><?php foreach($rows as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></p><p><label>Amount received</label><input type="number" min="0.01" step="0.01" name="amount" required></p><p><label>Note</label><input name="note"></p><button>Record Payment</button> <a class="btn secondary" href="?page=payments">Payment History</a></form></div></div><div class="card"><table><tr><th>Customer</th><th>WhatsApp</th><th class="right">Balance</th><th>Actions</th></tr><?php foreach($rows as $r):$bal=customer_balance($pdo,(int)$r['id']);$msg=str_replace(['{name}','{balance}'],[$r['name'],money($bal)],setting($pdo,'reminder_tamil'));$phone=whatsapp_number($r['mobile']);?><tr><td><?=e($r['name'])?></td><td><?php if($phone):?>+<?=e($phone)?> <span class="status-ready">Ready</span><?php elseif($r['mobile']):?><span class="status-check">Check number</span><?php else:?>—<?php endif;?></td><td class="right">₹<?=money($bal)?></td><td class="actions"><a href="?page=customers&edit=<?=$r['id']?>">Edit</a><a href="?page=ledger&customer_id=<?=$r['id']?>">Ledger</a><?php if($phone):?><a target="_blank" href="https://wa.me/<?=e($phone)?>?text=<?=rawurlencode($msg)?>">WhatsApp Reminder</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='ledger'){$customers=$pdo->query('SELECT id,name,mobile FROM customers ORDER BY name')->fetchAll();$customerId=(int)($_GET['customer_id']??0);$ledger=$customerId?customer_ledger($pdo,$customerId):['customer'=>null,'rows'=>[],'balance'=>0];$customer=$ledger['customer'];header_html('Customer Ledger');?><div class="actions no-print"><h1 style="margin-right:auto">Customer Ledger</h1></div><form method="get" class="card no-print ledger-search"><input type="hidden" name="page" value="ledger"><div class="grid"><p><label>Search customer</label><input id="ledger-customer-search" placeholder="Type customer name"></p><p><label>Select customer</label><select id="ledger-customer" name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>" data-name="<?=e(strtolower($c['name']))?>" <?=$customerId===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></p></div><button>View Ledger</button></form><?php if($customer):$phone=whatsapp_number($customer['mobile']);$msg=str_replace(['{name}','{balance}'],[$customer['name'],money($ledger['balance'])],setting($pdo,'reminder_tamil'));$pdfName='SGAS-Ledger-'.preg_replace('/[^A-Za-z0-9_-]+/','-',$customer['name']).'.pdf';?><div class="actions no-print ledger-actions"><button onclick="downloadDocumentPdf('<?=e($pdfName)?>')">Download PDF</button><button onclick="shareDocumentPdf('<?=e($pdfName)?>')">Share PDF</button><?php if($phone):?><a class="btn" target="_blank" href="https://wa.me/<?=e($phone)?>?text=<?=rawurlencode($msg)?>">WhatsApp Balance</a><?php endif;?></div><div class="card pdf-document ledger-print"><div class="ledger-header"><div><h1>SGAS</h1><p>Customer Ledger Statement</p></div><div><b><?=e($customer['name'])?></b><br><?=e($customer['mobile'])?><br><?=nl2br(e($customer['address']))?></div></div><table><thead><tr><th>Date</th><th>Type</th><th>Reference</th><th>Details</th><th class="right">Debit</th><th class="right">Credit</th><th class="right">Balance</th></tr></thead><tbody><?php foreach($ledger['rows'] as $r):?><tr><td><?=$r['timestamp']?e(date('d-m-Y',strtotime($r['timestamp']))):'—'?></td><td><?=e($r['type'])?></td><td><?=e($r['reference'])?></td><td><?=e($r['note'])?></td><td class="right"><?=$r['delta']>0?'₹'.money($r['delta']):'—'?></td><td class="right"><?=$r['delta']<0?'₹'.money(abs($r['delta'])):'—'?></td><td class="right"><b>₹<?=money($r['balance'])?></b></td></tr><?php endforeach;?></tbody></table><div class="ledger-closing"><span>Closing Balance</span><b>₹<?=money($ledger['balance'])?></b></div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script><?php endif;footer_html();exit;}

if($page==='payments'){$rows=$pdo->query('SELECT p.*,c.name customer FROM payments p JOIN customers c ON c.id=p.customer_id ORDER BY p.id DESC LIMIT 500')->fetchAll();header_html('Payments');?><div class="actions"><h1 style="margin-right:auto">Payment History</h1><a class="btn secondary" href="?page=customers">Record Payment</a></div><div class="card"><p class="muted">Reversals preserve the original record and restore the customer balance.</p><table><tr><th>ID</th><th>Customer</th><th>Recorded</th><th>Note</th><th class="right">Amount</th><th>Status</th><th></th></tr><?php foreach($rows as $r):$reversal=(float)$r['amount']<0;$reversed=str_starts_with($r['note'],'[REVERSED]');?><tr><td>#<?=$r['id']?></td><td><?=e($r['customer'])?></td><td><?=e(date('d-m-Y h:i A',strtotime($r['created_at'])))?></td><td><?=e($r['note'])?></td><td class="right <?=$reversal?'reversal-amount':''?>">₹<?=money($r['amount'])?></td><td><?=$reversal?'Reversal':($reversed?'Reversed':'Active')?></td><td><?php if(!$reversal&&!$reversed):?><form method="post" onsubmit="return confirm('Reverse this payment and restore the customer balance?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="reverse_payment"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Reverse</button></form><?php endif;?></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

if($page==='reports'){$from=trim($_GET['from']??date('Y-m-01'));$to=trim($_GET['to']??date('Y-m-d'));if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$to))$to=date('Y-m-d');if($from>$to)[$from,$to]=[$to,$from];$fromTs=$from.' 00:00:00';$toTs=date('Y-m-d H:i:s',strtotime($to.' +1 day'));$customers=$pdo->query("SELECT c.*,COALESCE(bs.bill_total,0) bill_total,COALESCE(bs.bill_received,0) bill_received,COALESCE(ps.payment_total,0) payment_total FROM customers c LEFT JOIN (SELECT customer_id,SUM(subtotal) bill_total,SUM(amount_received) bill_received FROM bills WHERE status='active' GROUP BY customer_id) bs ON bs.customer_id=c.id LEFT JOIN (SELECT customer_id,SUM(amount) payment_total FROM payments GROUP BY customer_id) ps ON ps.customer_id=c.id ORDER BY c.name")->fetchAll();$totalOutstanding=0.0;$readyCount=0;$missingCount=0;foreach($customers as &$c){$c['balance']=round((float)$c['opening_balance']+(float)$c['bill_total']-(float)$c['bill_received']-(float)$c['payment_total'],2);$c['phone']=whatsapp_number($c['mobile']);if($c['balance']>0){$totalOutstanding+=$c['balance'];if($c['phone'])$readyCount++;else $missingCount++;}}unset($c);$ps=$pdo->prepare("SELECT bi.product_id,MAX(bi.english_name) english_name,MAX(bi.tamil_name) tamil_name,MAX(bi.unit) unit,SUM(bi.quantity) quantity,SUM(bi.amount) sales_total,SUBSTRING_INDEX(GROUP_CONCAT(bi.rate ORDER BY b.created_at DESC,b.id DESC SEPARATOR ','),',',1) last_rate,MAX(b.created_at) last_sale FROM bill_items bi JOIN bills b ON b.id=bi.bill_id WHERE b.status='active' AND b.created_at>=? AND b.created_at<? GROUP BY bi.product_id ORDER BY sales_total DESC,english_name");$ps->execute([$fromTs,$toTs]);$productRows=$ps->fetchAll();$productTotal=array_sum(array_map(fn($r)=>(float)$r['sales_total'],$productRows));header_html('Reports');?><div class="reports-heading"><div><h1>Reports</h1><p>Outstanding, ledger, product sales and WhatsApp reminders</p></div><form method="get" class="card report-filter no-print"><input type="hidden" name="page" value="reports"><p><label>From</label><input type="date" name="from" value="<?=e($from)?>"></p><p><label>To</label><input type="date" name="to" value="<?=e($to)?>"></p><button>Apply</button><button type="button" class="btn secondary" onclick="window.print()">Print</button></form></div><div class="report-tabs no-print"><a class="report-tab" href="#outstanding">Customer Outstanding<span>₹<?=money($totalOutstanding)?></span></a><a class="report-tab" href="#ledger-access">Customer Ledger<span><?=count($customers)?></span></a><a class="report-tab" href="#product-sales">Product Sales<span>₹<?=money($productTotal)?></span></a><a class="report-tab" href="#whatsapp-report">WhatsApp Ready<span><?=$readyCount?></span></a></div><div class="report-summary"><div class="card"><small>Total Outstanding</small><b>₹<?=money($totalOutstanding)?></b></div><div class="card"><small>Customers Due</small><b><?=count(array_filter($customers,fn($c)=>$c['balance']>0))?></b></div><div class="card"><small>Period Sales</small><b>₹<?=money($productTotal)?></b></div><div class="card"><small>Missing WhatsApp</small><b><?=$missingCount?></b></div></div><section class="card report-section" id="outstanding"><div class="report-section-head"><div><h2>Customer Outstanding</h2><p>Complete balance calculated from opening balance, active bills and payments</p></div><span class="balance-positive">₹<?=money($totalOutstanding)?></span></div><div class="report-table-wrap"><table><thead><tr><th>Customer</th><th class="right">Opening</th><th class="right">Bills</th><th class="right">Received</th><th class="right">Balance</th><th class="no-report-print">Actions</th></tr></thead><tbody><?php foreach($customers as $c):$received=(float)$c['bill_received']+(float)$c['payment_total'];?><tr><td class="report-customer"><b><?=e($c['name'])?></b><small><?=e($c['mobile']?:$c['address'])?></small></td><td class="right">₹<?=money($c['opening_balance'])?></td><td class="right">₹<?=money($c['bill_total'])?></td><td class="right">₹<?=money($received)?></td><td class="right <?=$c['balance']>0?'balance-positive':'balance-clear'?>">₹<?=money($c['balance'])?></td><td class="no-report-print"><div class="report-actions"><a class="btn secondary" href="?page=ledger&customer_id=<?=$c['id']?>">Ledger</a><?php if($c['balance']>0&&$c['phone']):$msg=str_replace(['{name}','{balance}'],[$c['name'],money($c['balance'])],setting($pdo,'reminder_tamil'));?><a class="btn whatsapp-btn" target="_blank" href="https://wa.me/<?=e($c['phone'])?>?text=<?=rawurlencode($msg)?>">WhatsApp</a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="card report-section" id="ledger-access"><div class="report-section-head"><div><h2>Customer Ledger</h2><p>Open the complete debit, credit and running balance statement</p></div></div><form method="get" class="ledger-launch"><input type="hidden" name="page" value="ledger"><p><label>Select Customer</label><select name="customer_id" required><option value="">Choose customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?> — ₹<?=money($c['balance'])?></option><?php endforeach;?></select></p><button>Open Ledger</button></form></section><section class="card report-section" id="product-sales"><div class="report-section-head"><div><h2>Product Sales</h2><p><?=e(date('d-m-Y',strtotime($from)))?> to <?=e(date('d-m-Y',strtotime($to)))?></p></div><b>₹<?=money($productTotal)?></b></div><div class="report-table-wrap"><table><thead><tr><th>S.No</th><th>Product</th><th>Tamil Name</th><th>Unit</th><th class="right">Quantity</th><th class="right">Last Rate</th><th class="right">Sales Value</th><th>Last Sold</th></tr></thead><tbody><?php if(!$productRows):?><tr><td colspan="8" class="report-empty">No product sales in this date range.</td></tr><?php endif;foreach($productRows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['english_name'])?></td><td lang="ta"><?=e($r['tamil_name'])?></td><td><?=e($r['unit'])?></td><td class="right"><?=rtrim(rtrim(number_format((float)$r['quantity'],3),'0'),'.')?></td><td class="right">₹<?=money($r['last_rate'])?></td><td class="right"><b>₹<?=money($r['sales_total'])?></b></td><td><?=e(date('d-m-Y',strtotime($r['last_sale'])))?></td></tr><?php endforeach;?></tbody></table></div></section><section class="card report-section" id="whatsapp-report"><div class="report-section-head"><div><h2>WhatsApp Balance Reminders</h2><p>Only customers with an outstanding balance are listed</p></div><div><span class="report-status ready"><?=$readyCount?> Ready</span> <span class="report-status missing"><?=$missingCount?> Missing</span></div></div><div class="report-table-wrap"><table><thead><tr><th>Customer</th><th>WhatsApp Number</th><th class="right">Balance</th><th>Status</th><th class="no-report-print">Action</th></tr></thead><tbody><?php $hasDue=false;foreach($customers as $c):if($c['balance']<=0)continue;$hasDue=true;$msg=str_replace(['{name}','{balance}'],[$c['name'],money($c['balance'])],setting($pdo,'reminder_tamil'));?><tr><td class="report-customer"><b><?=e($c['name'])?></b><small><?=e($c['address'])?></small></td><td><?=$c['phone']?'+'.e($c['phone']):'—'?></td><td class="right balance-positive">₹<?=money($c['balance'])?></td><td><?=$c['phone']?'<span class="report-status ready">Ready</span>':'<span class="report-status missing">Add number</span>'?></td><td class="no-report-print"><?php if($c['phone']):?><a class="btn whatsapp-btn" target="_blank" href="https://wa.me/<?=e($c['phone'])?>?text=<?=rawurlencode($msg)?>">Send Reminder</a><?php else:?><a class="btn secondary" href="?page=customers&edit=<?=$c['id']?>">Add WhatsApp</a><?php endif;?></td></tr><?php endforeach;if(!$hasDue):?><tr><td colspan="5" class="report-empty">No outstanding balances.</td></tr><?php endif;?></tbody></table></div></section><?php footer_html();exit;}
if($page==='new_bill'||$page==='edit_bill'){$bill=null;$existing=[];if($page==='edit_bill'){$s=$pdo->prepare('SELECT * FROM bills WHERE id=?');$s->execute([(int)$_GET['id']]);$bill=$s->fetch();if(!$bill)exit('Bill not found.');$s=$pdo->prepare('SELECT * FROM bill_items WHERE bill_id=?');$s->execute([$bill['id']]);$existing=$s->fetchAll();}$customers=$pdo->query('SELECT * FROM customers ORDER BY name')->fetchAll();$selectedCustomer=null;foreach($customers as $candidate){if(($bill['customer_id']??0)==$candidate['id']){$selectedCustomer=$candidate;break;}}$displayBillNo=$bill?(int)$bill['bill_no']:(int)setting($pdo,'next_bill_no','1');$displayBillDate=$bill?date('Y-m-d',strtotime($bill['created_at'])):date('Y-m-d');header_html($bill?'Edit Bill':'New Bill');?><div class="page-heading"><div><h1><?=$bill?'Edit Bill #'.str_pad($bill['bill_no'],4,'0',STR_PAD_LEFT):'New Bill'?></h1></div></div><div class="price-popup" id="price-history-popup" hidden><div class="price-popup-card"><div class="price-popup-head"><div><small>Customer Price History</small><h3 id="price-popup-title">Last 5 Bills</h3></div><button type="button" class="price-popup-close" aria-label="Close">×</button></div><div class="price-popup-body"><table><thead><tr><th>Bill No.</th><th>Date</th><th class="right">Qty</th><th class="right">Rate</th></tr></thead><tbody id="price-popup-rows"></tbody></table></div></div></div><form method="post" class="card bill-form" id="bill-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save_bill"><input type="hidden" name="bill_id" value="<?=e($bill['id']??'')?>"><div class="bill-top"><div class="customer-area"><div class="customer-search-row"><div class="customer-field searchbox"><label>Customer Name</label><input id="bill-customer-search" placeholder="Type customer name or mobile" autocomplete="off" value="<?=e($selectedCustomer?($selectedCustomer['name'].' — '.(trim($selectedCustomer['address'])!==''?$selectedCustomer['address']:'Address not available')):'')?>" required><button type="button" class="customer-clear" aria-label="Clear selected customer" <?=$selectedCustomer?'':'hidden'?>>×</button><input type="hidden" id="bill-customer" name="customer_id" value="<?=e($selectedCustomer['id']??'')?>" data-balance="<?=$selectedCustomer?customer_balance($pdo,(int)$selectedCustomer['id'],$bill['id']??null):0?>"><div class="suggestions customer-suggestions" id="customer-suggestions"><?php foreach($customers as $c):$cb=customer_balance($pdo,(int)$c['id'],$bill['id']??null);?><button type="button" data-id="<?=$c['id']?>" data-name="<?=e($c['name'])?>" data-mobile="<?=e($c['mobile'])?>" data-address="<?=e($c['address'])?>" data-search="<?=e(strtolower($c['name'].' '.$c['mobile']))?>" data-balance="<?=$cb?>"><strong><?=e($c['name'])?></strong><small><?=trim($c['address'])!==''?e($c['address']):'Address not available'?></small></button><?php endforeach;?></div></div><a class="btn secondary add-customer-link" href="?page=customers">＋ Add Customer</a></div></div><div class="bill-info-stack"><div><label>Bill Date</label><input type="date" name="bill_date" value="<?=e($displayBillDate)?>" required></div><div><small>Bill No.</small><b>#<?=str_pad((string)$displayBillNo,4,'0',STR_PAD_LEFT)?></b></div></div></div><div class="items-table-head"><span>S.No</span><span>Product (English Search)</span><span>Qty</span><span>Unit</span><span>Rate</span><span>Amount</span><span></span></div><div id="items"></div><div class="bill-footer"><div class="bill-summary"><div><small>Previous Balance</small><b>₹<span id="previous-balance">0.00</span></b></div><div><small>Current Bill</small><b>₹<span id="subtotal">0.00</span></b></div><div><label>Amount Received</label><input id="bill-received" type="number" name="amount_received" min="0" step="0.01" value="<?=e($bill['amount_received']??'0')?>"></div><div class="closing-box"><small>Closing Balance</small><b>₹<span id="closing-balance">0.00</span></b></div></div><div class="bill-actions"><a class="btn secondary" href="<?=$bill?'?page=bills':'index.php'?>">Cancel</a><button class="save-bill"><?=$bill?($bill['status']==='cancelled'?'Save & Restore Bill':'Save Changes'):'Save & Create Bill'?></button></div></div></form><template id="item-template"><div class="item-row"><div class="sno-cell"><label>S.No</label><b class="row-number">1</b></div><div class="product-cell searchbox"><label>Product</label><input class="product-search" name="english_name[]" autocomplete="off" required><input type="hidden" class="product-id" name="product_id[]"><input type="hidden" class="tamil-name" name="tamil_name[]"><div class="suggestions"></div></div><div><label>Qty</label><input class="qty numeric" name="quantity[]" type="number" min="0.001" step="0.001" value="1"></div><div><label>Unit</label><input class="unit" name="unit[]" readonly></div><div><label>Rate</label><input class="rate numeric" name="rate[]" type="number" min="0" step="0.01"></div><div><label>Amount</label><input class="amount numeric" readonly></div><button type="button" class="danger remove" aria-label="Remove row">×</button></div></template><?php if($existing):?><script>window.addEventListener('DOMContentLoaded',()=>{<?php foreach($existing as $x):?>addRow(<?=json_encode(['product_id'=>$x['product_id'],'english_name'=>$x['english_name'],'tamil_name'=>$x['tamil_name'],'unit'=>$x['unit'],'default_rate'=>$x['rate']],JSON_UNESCAPED_UNICODE)?>);let r=document.querySelector('#items .item-row:last-child');r.querySelector('.qty').value=<?=json_encode($x['quantity'])?>;recalc();<?php endforeach;?>});</script><?php endif;footer_html();exit;}

if($page==='bills'){$rows=$pdo->query('SELECT b.*,c.name customer FROM bills b JOIN customers c ON c.id=b.customer_id ORDER BY b.id DESC')->fetchAll();header_html('Bills');?><div class="actions"><h1 style="margin-right:auto">Bills</h1><a class="btn" href="?page=new_bill">New Bill</a></div><div class="card"><table><tr><th>Bill No.</th><th>Date</th><th>Customer</th><th class="right">Total</th><th>Status</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=str_pad($r['bill_no'],4,'0',STR_PAD_LEFT)?></td><td><?=e(date('d-m-Y',strtotime($r['created_at'])))?></td><td><?=e($r['customer'])?></td><td class="right">₹<?=money($r['subtotal'])?></td><td><?=e(ucfirst($r['status']))?></td><td><div class="actions bill-row-actions"><a class="btn secondary" href="?page=view_bill&id=<?=$r['id']?>">View / Print</a><?php if($r['status']==='active'):?><a class="btn" href="?page=edit_bill&id=<?=$r['id']?>">Edit</a><?php else:?><a class="btn" href="?page=edit_bill&id=<?=$r['id']?>" onclick="return confirm('Editing and saving will restore this cancelled bill and update the customer balance. Continue?')">Edit & Restore</a><?php endif;?></div></td></tr><?php endforeach;?></table></div><?php footer_html();exit;}

